              "x": 740,
              "y": 294,
              "w": 230,
              "h": 130
            }
          },
          {
            "item": "viz_7",
            "type": "block",
            "position": {
              "x": 980,
              "y": 294,
              "w": 460,
              "h": 130
            }
          },
          {
            "item": "viz_8",
            "type": "block",
            "position": {
              "x": 20,
              "y": 444,
              "w": 700,
              "h": 360
            }
          },
          {
            "item": "viz_9",
            "type": "block",
            "position": {
              "x": 740,
              "y": 444,
              "w": 700,
              "h": 360
            }
          },
          {
            "item": "viz_10",
            "type": "block",
            "position": {
              "x": 20,
